const config = $('Leer configuración de indexación').first().json.data;
if (config.collection !== 'rutaia_courses_gemini_1536') throw new Error('Destino de indexación no permitido');
const courses = $('Leer catálogo PostgreSQL').first().json.data?.items;
if (!Array.isArray(courses)) throw new Error('Respuesta del catálogo inválida');
return [{ json: { ...config, courses, emptyCatalog: courses.length === 0, inputs: courses.map(c => `Curso: ${c.name}
Descripción: ${c.description}
Categoría: ${c.category}
Nivel RutaIA: ${c.level}
Clasificación INTECAP: ${c.intecapCareerType ?? 'No indicada'}
Duración: ${c.durationHours} horas`) } }];

const response = $input.first().json;
if (response.statusCode === 404) return [{ json: { cleared: false, reason: 'collection_not_created' } }];
if (!Number.isInteger(response.statusCode) || response.statusCode < 200 || response.statusCode >= 300) throw new Error('Qdrant no pudo limpiar los vectores de catálogo vacío');
return [{ json: { cleared: true } }];

const cfg = $('Preparar textos de cursos').first().json;
const result = $input.first().json;
const vectors = result.embeddings ?? result.body?.embeddings;
if (!Array.isArray(vectors) || vectors.length !== cfg.courses.length) throw new Error('Gemini devolvió una cantidad de embeddings inválida');
const dimension = vectors[0]?.length;
if (!Number.isInteger(dimension) || dimension < 1) throw new Error('Dimensión de embedding inválida');
if (cfg.collection !== 'rutaia_courses_gemini_1536' || dimension !== 1536) throw new Error('Destino de indexación no permitido');
for (const vector of vectors) if (!Array.isArray(vector) || vector.length !== dimension || vector.some(n => !Number.isFinite(n))) throw new Error('Los embeddings no tienen dimensión o valores válidos');
const points = cfg.courses.map((course, i) => ({ id: course.id, vector: vectors[i], payload: { course_id: course.id, name: course.name, description: course.description, category: course.category, level: course.level, intecap_career_type: course.intecapCareerType ?? null, duration_hours: course.durationHours, is_active: true } }));
return [{ json: { qdrantUrl: cfg.qdrantUrl.replace(/\/$/, ''), collection: cfg.collection, dimension, points } }];
